"""Fixture/factory layer for OrderDAO tests.

Every test gets a fresh in-memory SQLite database (function-scoped conn
fixture), so no state can leak between tests.
"""

import sqlite3
from itertools import count

import pytest

from orderdao import SCHEMA


@pytest.fixture
def conn():
    """Fresh in-memory DB with schema applied and foreign keys enforced."""
    c = sqlite3.connect(":memory:")
    c.execute("PRAGMA foreign_keys = ON")
    assert c.execute("PRAGMA foreign_keys").fetchone()[0] == 1  # sanity check
    c.executescript(SCHEMA)
    yield c
    c.close()


@pytest.fixture
def dao(conn):
    from orderdao import OrderDAO
    return OrderDAO(conn)


# --- Factories -------------------------------------------------------------
# Sequential defaults via itertools.count; each call inserts a row and
# returns the new row's id. Overrides win over defaults.

_customer_seq = count(1)
_order_seq = count(100)


@pytest.fixture
def make_customer(conn):
    def _make(**overrides):
        defaults = {
            "name": f"Customer #{next(_customer_seq)}",
            "email": f"customer{next(_customer_seq)}@example.com",
        }
        row = {**defaults, **overrides}
        cur = conn.execute(
            "INSERT INTO customers (name, email) VALUES (?, ?)",
            (row["name"], row["email"]),
        )
        conn.commit()
        return cur.lastrowid
    return _make


@pytest.fixture
def make_order(conn, make_customer):
    def _make(**overrides):
        # Auto-create a backing customer unless one is supplied.
        overrides.setdefault("customer_id", make_customer())
        row = {"total_cents": next(_order_seq) * 100, **overrides}
        cur = conn.execute(
            "INSERT INTO orders (customer_id, total_cents) VALUES (?, ?)",
            (row["customer_id"], row["total_cents"]),
        )
        conn.commit()
        return cur.lastrowid
    return _make

