def _order_row(conn, order_id):
    return conn.execute(
        "SELECT customer_id, status FROM orders WHERE id = ?", (order_id,)
    ).fetchone()


def test_status_transitions(dao, conn, make_order):
    """All legal transitions stick; the default is 'new'."""
    oid = make_order()
    assert _order_row(conn, oid)[1] == "new"

    for status in ("paid", "shipped", "cancelled", "new"):
        dao.set_status(oid, status)
        assert _order_row(conn, oid)[1] == status
